package app.layan.test;
import android.app.*;import android.content.*;import android.content.res.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import dalvik.system.DexClassLoader;import java.io.*;import java.lang.reflect.*;import java.util.*;import app.layan.quran.prayer.*;import org.threeten.bp.*;
public final class PrayerRegression extends Instrumentation {
 private final StringBuilder report=new StringBuilder();private Bundle args;private int comparisons;
 public void onCreate(Bundle a){super.onCreate(a);args=a;start();}
 private void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 private void log(String s){report.append(s).append('\n');android.util.Log.i("LayanRegression",s);}
 private Calendar calendar(LocalDate d){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("UTC"));c.clear();c.set(d.getYear(),d.getMonthValue()-1,d.getDayOfMonth(),12,0,0);return c;}
 private void oracle()throws Exception{
  Context context=getTargetContext();File ref=new File("/data/local/tmp/prayer-reference.apk");DexClassLoader original=new DexClassLoader(ref.getPath(),context.getCodeCacheDir().getPath(),null,Context.class.getClassLoader());Class<?> prefsClass=original.loadClass("k7.a");SharedPreferences prefs=context.getSharedPreferences("prayer_oracle",0);prefs.edit().clear().commit();prefsClass.getField("a").set(null,context);prefsClass.getField("f").set(null,prefs);
  Class<?> engine=original.loadClass("m4.e"),adjustment=original.loadClass("com.angga.ahisab.preference.adjustment.Adjustment");Constructor<?> ctor=engine.getConstructor(String.class,int.class,double.class,double.class,double.class,List.class,boolean.class);
  String[] methods={"karachi","isna","mwl","ega","uau","moonsighting","at","jakim","muis","diyanet","uiof","custom"};double[][] coords={{30.0444,31.2357},{21.4225,39.8262},{51.5074,-.1278},{-33.8688,151.2093},{40.7128,-74.006}};String[] dates={"2026-01-15","2026-04-24","2026-07-15","2026-10-30"};
  for(String method:methods)for(int asr=0;asr<2;asr++)for(double[] point:coords)for(String ds:dates){LocalDate date=LocalDate.parse(ds);Map<String,Object> opts=new HashMap<>();opts.put("high_latitude_method",2);opts.put("pref_juristic",asr);prefs.edit().clear().putInt("high_latitude_method",2).commit();List<Object> offsets=new ArrayList<>();Object oracle=ctor.newInstance(method,asr,point[0],point[1],-9999d,offsets,false);engine.getMethod("c",Calendar.class,String.class,boolean.class,boolean.class).invoke(oracle,calendar(date),"UTC",true,true);Map<?,?> values=(Map<?,?>)engine.getField("e").get(oracle);ReferencePrayer actual=new ReferencePrayer(point[0],point[1],-9999,ZoneId.of("UTC"),method,opts);List<ReferencePrayer.Event> events=actual.times(date);
   for(String id:ReferencePrayer.IDS){Number number=(Number)values.get(id);if(number==null||!Double.isFinite(number.doubleValue()))continue;long expected=(long)Math.floor(number.doubleValue()*60+.5);ReferencePrayer.Event event=null;for(ReferencePrayer.Event e:events)if(e.id.equals(id))event=e;check(event!=null,"Missing "+id);long delta=event.instant.getEpochSecond()-date.atStartOfDay(ZoneId.of("UTC")).toEpochSecond();check(delta==expected*60,method+" "+ds+" "+id+" expected "+expected+" actual "+delta/60);comparisons++;}
  }
  log("Original APK engine parity: "+comparisons+" event comparisons across 12 methods, 2 Asr rules, 5 locations and 4 dates.");
  Class<?> astro=original.loadClass("e5.h"),coordinate=original.loadClass("f5.e");Object astronomy=astro.getField("a").get(null);for(double[] point:coords)for(String ds:dates){Calendar c=calendar(LocalDate.parse(ds));Object data=astro.getMethod("f",Calendar.class,coordinate).invoke(astronomy,c,coordinate.getConstructor(double.class,double.class).newInstance(point[0],point[1]));double[] actual=new ReferencePrayer(point[0],point[1],0,ZoneId.of("UTC"),"ega",Collections.emptyMap()).moon(Instant.ofEpochMilli(c.getTimeInMillis()));String[] fields={"a","b","c","d"};for(int i=0;i<4;i++)check(Math.abs(actual[i]-data.getClass().getField(fields[i]).getDouble(data))<1e-10,"Moon mismatch "+ds+" "+i);}
  log("Moon astronomy parity: all four phase/orientation outputs matched original APK at 20 location/date combinations.");
 }
 private void dst(){ZoneId zone=ZoneId.of("Africa/Cairo");ReferencePrayer engine=new ReferencePrayer(30.0444,31.2357,-9999,zone,"ega",Collections.emptyMap());for(String ds:new String[]{"2026-01-15","2026-04-23","2026-04-24","2026-07-15","2026-10-29","2026-10-30"}){LocalDate d=LocalDate.parse(ds);List<ReferencePrayer.Event> times=engine.times(d);for(ReferencePrayer.Event e:times){check(e.instant.atZone(zone).getSecond()==0,"minute rounding");long now=e.instant.minusSeconds(3600).toEpochMilli();check(ReferencePrayer.secondsLeft(now,e.instant.toEpochMilli())==3600,"DST countdown");}ReferencePrayer.Event next=engine.next(d.atTime(23,55).atZone(zone).toInstant());check(next.id.equals("fajr"),"next-day Fajr");check(next.instant.atZone(zone).toLocalDate().equals(d.plusDays(1)),"Fajr date");}check(zone.getRules().getOffset(Instant.parse("2026-07-15T12:00:00Z")).getTotalSeconds()==10800,"Cairo summer rules");check(zone.getRules().getOffset(Instant.parse("2026-01-15T12:00:00Z")).getTotalSeconds()==7200,"Cairo winter rules");log("Cairo winter, summer and DST transition dates: table, event clock and countdown share one instant; next-day Fajr correct.");}
 private String texts(View v){StringBuilder b=new StringBuilder();if(v instanceof TextView)b.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)b.append(texts(((ViewGroup)v).getChildAt(i)));return b.toString();}
 private Object field(Activity a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 private void drain(Activity a)throws Exception{for(int i=0;i<600;i++){waitForIdleSync();if(field(a,"next")!=null)return;SystemClock.sleep(100);}throw new AssertionError("Prayer screen did not calculate: "+texts(a.getWindow().getDecorView()));}
 private void shot(Activity a,String name)throws Exception{SystemClock.sleep(300);Bitmap image=NativeScreens.capture(this,a);log("Screenshot "+name+": "+NativeScreens.lastMode);File f=new File(a.getExternalFilesDir("tests"),name);f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
 private void widgets(Activity a)throws Exception{PrayerWidget[] types={new PrayerWidget.Horizontal(),new PrayerWidget.Vertical(),new PrayerWidget.Mini(),new PrayerWidget.Minimal(),new PrayerWidget.Clock()};for(PrayerWidget provider:types){final View[] rendered=new View[1];runOnMainSync(()->{android.widget.RemoteViews r=provider.render(a);rendered[0]=r.apply(a,null);});SharedPreferences saved=a.getSharedPreferences("layan_local",0);long lat=saved.getLong("prayer_lat",0),lon=saved.getLong("prayer_lon",0);saved.edit().remove("prayer_lat").remove("prayer_lon").commit();runOnMainSync(()->provider.render(a).reapply(a,rendered[0]));saved.edit().putLong("prayer_lat",lat).putLong("prayer_lon",lon).commit();runOnMainSync(()->provider.render(a).reapply(a,rendered[0]));check(rendered[0].findViewById(a.getResources().getIdentifier("lp_widget_countdown","id",a.getPackageName())).getVisibility()==View.VISIBLE,"widget location recovery");if(provider instanceof PrayerWidget.Clock){TextClock clock=(TextClock)rendered[0].findViewById(a.getResources().getIdentifier("lp_widget_clock","id",a.getPackageName()));String offset="GMT"+ZoneId.of("Africa/Cairo").getRules().getOffset(Instant.now()).getId().replace("Z","+00:00");check(offset.equals(clock.getTimeZone()),"Widget clock must use current DST offset, even with old OS TZDB");}String content=texts(rendered[0]);check(content.contains("Africa/Cairo") && !content.contains("Open prayer times"),"widget event "+provider.getClass()+": "+content);runOnMainSync(()->{android.widget.FrameLayout host=new android.widget.FrameLayout(a);host.setBackgroundColor(0xffdedfda);host.setPadding(16,30,16,20);host.addView(rendered[0],new android.widget.FrameLayout.LayoutParams((int)(a.getResources().getDisplayMetrics().density*(provider instanceof PrayerWidget.Vertical?180:provider instanceof PrayerWidget.Mini?170:340)),(int)(a.getResources().getDisplayMetrics().density*(provider instanceof PrayerWidget.Vertical?350:provider instanceof PrayerWidget.Mini?140:200))));a.setContentView(host);});waitForIdleSync();shot(a,"widget-"+provider.getClass().getSimpleName()+"-"+Resources.getSystem().getConfiguration().getLocales().get(0).getLanguage()+".png");}log("All five prayer widget RemoteViews rendered without inflation errors.");}
 private void ui()throws Exception{Context c=getTargetContext();c.getSharedPreferences("layan_local",0).edit().clear().putLong("prayer_lat",Double.doubleToLongBits(30.0444)).putLong("prayer_lon",Double.doubleToLongBits(31.2357)).putLong("prayer_location_time",System.currentTimeMillis()).putFloat("prayer_accuracy",100).putString("lp_zone","LOCATION").commit();for(String lang:new String[]{Resources.getSystem().getConfiguration().getLocales().get(0).toLanguageTag()}){Activity a=startActivitySync(new Intent().setClassName(c,"app.layan.quran.PrayerActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));drain(a);String text=texts(a.getWindow().getDecorView());check(text.contains("Africa/Cairo"),"Location zone");check(text.contains(lang.startsWith("ar")?"أوقات الصلاة":"Prayer times"),"Phone locale "+lang+": "+text);check(text.contains(lang.startsWith("ar")?"الفجر":"Fajr"),"prayer labels "+lang);check(field(a,"moonView")!=null,"Moon absent");shot(a,"prayer-"+lang+".png");runOnMainSync(()->{try{Method settings=a.getClass().getDeclaredMethod("calculationSettings");settings.setAccessible(true);settings.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();String settingsText=texts(a.getWindow().getDecorView());check(settingsText.contains(lang.startsWith("ar")?"العصر":"Asr"),"Asr settings");check(!settingsText.toLowerCase(Locale.ROOT).contains("adhan"),"unrequested Adhan");shot(a,"prayer-settings-"+lang+".png");runOnMainSync(()->a.onBackPressed());drain(a);runOnMainSync(()->{try{Field next=a.getClass().getDeclaredField("next");next.setAccessible(true);next.set(a,null);Field month=a.getClass().getDeclaredField("monthly");month.setAccessible(true);month.setBoolean(a,true);Method compute=a.getClass().getDeclaredMethod("compute");compute.setAccessible(true);compute.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});drain(a);waitForIdleSync();shot(a,"prayer-month-"+lang+".png");widgets(a);runOnMainSync(()->a.finish());log("Prayer, settings and month views opened in phone locale "+lang+".");}}
 private void widgetOnly()throws Exception{Context c=getTargetContext();c.getSharedPreferences("layan_local",0).edit().putLong("prayer_lat",Double.doubleToLongBits(30.0444)).putLong("prayer_lon",Double.doubleToLongBits(31.2357)).putLong("prayer_location_time",System.currentTimeMillis()).putString("lp_zone","LOCATION").commit();Configuration system=new Configuration(Resources.getSystem().getConfiguration());system.setLocales(new LocaleList(Locale.forLanguageTag("ar-EG")));Resources.getSystem().updateConfiguration(system,Resources.getSystem().getDisplayMetrics());Activity a=startActivitySync(new Intent().setClassName(c,"app.layan.quran.PrayerActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));drain(a);shot(a,"prayer-ar-final.png");widgets(a);runOnMainSync(()->a.finish());log("Widgets reapply after location recovery and clock matches current Cairo DST offset.");}
 public void onStart(){Bundle out=new Bundle();int result=Activity.RESULT_OK;try{if(args!=null&&"calculations".equals(args.getString("mode"))){oracle();dst();}else if(args!=null&&"widgets".equals(args.getString("mode")))widgetOnly();else{if(args==null||!"ui".equals(args.getString("mode"))){oracle();dst();}ui();}out.putString("result","PASS");}catch(Throwable e){result=Activity.RESULT_CANCELED;log(android.util.Log.getStackTraceString(e));out.putString("error",e.toString());}try{File f=new File(getTargetContext().getExternalFilesDir("tests"),"prayer-regression.log");f.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(f)){stream.write(report.toString().getBytes("UTF-8"));}}catch(Exception ignored){}out.putString("report",report.toString());finish(result,out);}
}
